package cl.nexbyte.siger.institucional.formulario;
import cl.nexbyte.siger.institucional.robustez.*;import org.junit.jupiter.api.*;import java.util.concurrent.atomic.AtomicLong;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class PlanificadorFormularioTest {
 RecuperarFormulario receiver=mock(RecuperarFormulario.class);ControlesOperacion control=mock(ControlesOperacion.class);AtomicLong now=new AtomicLong(1000);FormularioInstitucionalConfiguration.Planificador scheduler=new FormularioInstitucionalConfiguration.Planificador(receiver,control,now::get);
 @BeforeEach void prepare(){when(control.estado()).thenReturn(new ControlesOperacion.Control(1,true,true,"NORMAL"));when(receiver.ejecutar()).thenReturn(new RecuperarFormulario.Resultado(0,0,0,false));}
 @Test void pausaNoConsultaNiConcilia(){when(control.estado()).thenReturn(new ControlesOperacion.Control(2,true,false,"NORMAL"));scheduler.tick();verifyNoInteractions(receiver);assertEquals("PAUSADO_POR_CONTROL",scheduler.estado().estado());}
 @Test void conciliaAntesDeReclamarYCuentaSoloResultadosReales(){when(receiver.conciliar()).thenReturn(2);when(receiver.ejecutar()).thenReturn(new RecuperarFormulario.Resultado(1,1,0,false));scheduler.tick();var order=inOrder(receiver);order.verify(receiver).conciliar();order.verify(receiver).ejecutar();assertEquals(1,scheduler.estado().confirmadas());assertEquals(2,scheduler.estado().conciliadas());assertEquals("RECEPCION_CONFIRMADA",scheduler.estado().estado());}
 @Test void colaVaciaSigueSondeandoSinCrearRegistros(){scheduler.tick();now.addAndGet(5000);scheduler.tick();assertEquals(2,scheduler.estado().ciclos());assertEquals(0,scheduler.estado().recuperadas());assertEquals("ESPERANDO_ENTREGAS",scheduler.estado().estado());}
 @Test void indisponibilidadRetrocedeYSeRecuperaSinMensajesSensibles(){when(receiver.ejecutar()).thenThrow(new FalloTecnico(503));scheduler.tick();assertEquals("HTTP_503",scheduler.estado().ultimoError());assertEquals(11000,scheduler.estado().proximoIntentoMs());scheduler.tick();verify(receiver,times(1)).ejecutar();now.set(11000);doReturn(new RecuperarFormulario.Resultado(0,0,0,false)).when(receiver).ejecutar();scheduler.tick();assertEquals("ESPERANDO_ENTREGAS",scheduler.estado().estado());assertEquals(0,scheduler.estado().fallosConsecutivos());}
 @Test void entregaNoConfirmadaNoSeCuentaComoExito(){when(receiver.ejecutar()).thenReturn(new RecuperarFormulario.Resultado(1,0,1,false));scheduler.tick();assertEquals(0,scheduler.estado().confirmadas());assertEquals("ENTREGA_NO_CONFIRMADA",scheduler.estado().ultimoError());assertEquals("REINTENTO_PROGRAMADO",scheduler.estado().estado());}
 @Test void perdidaDeExclusionImpideCualquierHttp(){var source=mock(FuenteFormulario.class);var job=new RecuperarFormulario(source,mock(RecepcionInstitucionalJdbc.class),mock(ArchivoInstitucional.class),()->{throw new IllegalStateException("sin lock");});assertThrows(IllegalStateException.class,job::ejecutar);assertThrows(IllegalStateException.class,job::conciliar);verifyNoInteractions(source);}
}
